import{c as p,Z as d,Q as r,j as c,m as a,g as l,n as s,o,av as i}from"./chunks/framework.rWdQudnF.js";const A=JSON.parse('{"title":"错题记录","description":"","frontmatter":{"title":"错题记录"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/错题记录.md","filePath":"综合知识/系统基础/操作系统/错题记录.md","lastUpdated":null}'),e={name:"综合知识/系统基础/操作系统/错题记录.md"},u={class:"callout callout-note"},g={class:"callout-body"};function h(m,t,b,y,C,v){const n=d("font");return r(),c("div",null,[t[9]||(t[9]=a('<hr><p><strong>[Q54] 信号量值含义</strong></p><p>若信号量S的初始值为3，当前值为-1，则表示（ ）个进程正在等待该资源。</p><ul><li>A. 0</li><li>B. 1</li><li>C. 2</li><li>D. 3</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：S&lt;0时，|S|=等待进程数。|-1|=1个进程在等待。</p><p>这道题考的是 <strong>信号量值的含义</strong>，规则很简单：</p><p><strong>信号量 S 的含义：</strong></p><ul><li>S ≥ 0 → S 表示<strong>可用资源数</strong></li><li>S &lt; 0 → |S| 表示<strong>等待该资源的进程数</strong></li></ul><hr><p><strong>逐步推演：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>S 值变化</th><th>说明</th></tr></thead><tbody><tr><td>初始</td><td>S = 3</td><td>3 个资源可用</td></tr><tr><td>进程 A 执行 P 操作</td><td>S = 2</td><td>占用 1 个，剩 2 个可用</td></tr><tr><td>进程 B 执行 P 操作</td><td>S = 1</td><td>占用 2 个，剩 1 个可用</td></tr><tr><td>进程 C 执行 P 操作</td><td>S = 0</td><td>占用 3 个，<strong>资源刚好用完</strong></td></tr><tr><td>进程 D 执行 P 操作</td><td><strong>S = -1</strong></td><td>资源已用完，<strong>D 进入等待队列</strong></td></tr></tbody></table><p>当 S = -1：</p><ul><li>绝对值 |-1| = <strong>1</strong> → 有 <strong>1 个进程</strong>在等待（进程 D）</li><li>同时意味着 3 个资源全被占用</li></ul><p><strong>所以选 B（1 个进程等待）</strong></p></div></details><hr><p><strong>[Q66] 前趋图PV规则</strong></p><p>在使用信号量实现前驱关系时，以下哪个步骤是正确的（ ）。</p><ul><li>A. 设置的信号量数量等于进程数</li><li>B. 所有信号量的初始值设为1</li><li>C. 进程执行前进行V操作，执行后进行P操作</li><li>D. 信号量数量等于有向边数量，初始值为0</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：信号量数=有向边数，初值全0，前驱执行后V，后继执行前P。</p></div></details><hr><p><strong>[Q64] 死锁条件</strong></p><p>在操作系统中，以下哪个条件不是产生死锁的必要条件（ ）。</p><ul><li>A. 资源共享</li><li>B. 保持和等待</li><li>C. 不可剥夺</li><li>D. 环路等待</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：死锁四条件：互斥、占有等待、不可剥夺、环路等待。&quot;资源共享&quot;不是。</p><p>死锁四个必要条件</p><table tabindex="0"><thead><tr><th>条件</th><th>含义</th></tr></thead><tbody><tr><td><strong>互斥</strong></td><td>资源一次只能给一个进程用</td></tr><tr><td><strong>保持和等待</strong></td><td>进程占着资源不放，还等别的资源</td></tr><tr><td><strong>不可剥夺</strong></td><td>资源不能被强行抢走</td></tr><tr><td><strong>环路等待</strong></td><td>进程间形成循环等待链</td></tr><tr><td>选 A 的原因</td><td></td></tr></tbody></table><p><strong>A. 资源共享</strong> ❌ — 不是必要条件</p><ul><li>死锁需要的是<strong>互斥（资源不能共享）</strong>，而不是共享</li><li>如果一个资源可以共享（比如只读文件），多个进程同时用不会死锁</li><li>所以「资源共享」恰恰是<strong>避免</strong>死锁的方向，不是产生死锁的条件</li></ul></div></details><hr><p><strong>[Q9] 并发+死锁</strong></p><p>若一个单处理器的计算机系统中同时存在3个并发进程，则同一时刻允许占用处理器的进程数（ ）；如果这3个进程都要求使用2个互斥资源R，那么系统不产生死锁的最少的R资源数为（ ）个。</p><ul><li>A. 至少为1个</li><li>B. 至少为3个</li><li>C. 最多为1个</li><li>D. 最多为3个</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C（最多1个）</p><p>解析：单处理器同一时刻最多1个进程占用CPU。死锁最小资源=3×(2-1)+1=4，选项未给出第二问。</p></div></details><hr><p><strong>[Q72] 调度</strong></p><p>在操作系统中，哪种调度不涉及进程在内存和外存之间的交换（ ）。</p><ul><li>A. 高级调度</li><li>B. 中级调度</li><li>C. 低级调度</li><li>D. 实时调度</li></ul>',24)),l("details",u,[t[6]||(t[6]=l("summary",{class:"callout-title"},[l("span",{class:"callout-icon"},"📝"),s("答案与解析")],-1)),l("div",g,[t[2]||(t[2]=a('<p>答案：C</p><p>解析：低级调度=CPU分配，不涉及内存-外存交换；中级调度才涉及。</p><p>这道题选 <strong>C（低级调度）</strong> ✅。<code>实时调度</code> 不是三级调度中的概念，是两个不同的维度。</p><hr><p>三级调度回顾</p><table tabindex="0"><thead><tr><th>调度级别</th><th>别名</th><th>做什么</th><th style="text-align:center;">是否涉及内外存交换</th></tr></thead><tbody><tr><td><strong>高级调度</strong></td><td>作业调度</td><td>决定哪个后备作业调入内存成为就绪进程</td><td style="text-align:center;">✅ 是</td></tr><tr><td><strong>中级调度</strong></td><td>对换调度</td><td>决定交换区中哪个进程换入内存</td><td style="text-align:center;">✅ 是</td></tr><tr><td><strong>低级调度</strong></td><td>进程调度</td><td>决定内存中哪个就绪进程拿到 CPU</td><td style="text-align:center;">❌ <strong>否</strong></td></tr></tbody></table><p>低级调度只看<strong>谁上 CPU</strong>，进程已经在内存里了，不涉及搬进搬出。所以选 C。</p><hr>',8)),o(n,{color:"#f79646"},{default:i(()=>[...t[0]||(t[0]=[s('实时调度不是"第四个级别"',-1)])]),_:1}),t[3]||(t[3]=a(`<p><strong>实时调度</strong>是调度<strong>算法/策略的分类</strong>，而不是一个独立的调度级别。</p><p>三级调度是按<strong>发生的位置和时机</strong>分的（作业层→交换层→CPU 层），而实时调度是按<strong>调度目标</strong>分的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调度策略分类：  </span></span>
<span class="line"><span>├── 先来先服务（FCFS）  </span></span>
<span class="line"><span>├── 时间片轮转（RR）  </span></span>
<span class="line"><span>├── 优先级调度  </span></span>
<span class="line"><span>├── 多级反馈队列  </span></span>
<span class="line"><span>└── 实时调度（保证任务在截止时间前完成）  </span></span>
<span class="line"><span>        ├── 速率单调调度（RMS）— 静态优先级  </span></span>
<span class="line"><span>        └── 最早截止时间优先（EDF）— 动态优先级</span></span></code></pre></div><p><strong>实时调度</strong>关注的是<strong>能不能按时完成</strong>，它在三级调度中属于<strong>低级调度</strong>这个层面 — 决定当前哪个进程上 CPU，只是选谁的标准变了（看截止时间而非优先级/时间片）。</p><hr>`,5)),o(n,{color:"#4bacc6"},{default:i(()=>[...t[1]||(t[1]=[s("一句话区分",-1)])]),_:1}),t[4]||(t[4]=l("p",null,[s("高级/中级/低级 = "),l("strong",null,"在哪个阶段做调度"),s(" 实时调度 = "),l("strong",null,"用什么标准来做调度"),s("（按时完成优先）")],-1)),t[5]||(t[5]=l("p",null,[s("所以题目中的 D 选项其实是一个分类错误 — 它和 A/B/C 不在同一个维度上。但标准答案还是 "),l("strong",null,"C（低级调度）"),s("，因为它是唯一明确不涉及内外存交换的")],-1))])]),t[10]||(t[10]=a(`<hr><blockquote><p>⭐ <strong>经典题目</strong> — 链式存储+成组分解字节定位易错（块号从0计数，整除为边界）</p></blockquote><p><strong>[Q20] 链式存储+成组分解</strong></p><p>某文件系统采用链式存储管理方式并应用记录的成组与分解技术，且磁盘块的大小为 4096 字节。若文件 license.doc 由 7 个逻辑记录组成，每个逻辑记录的大小为 2048字节，并依次存放在 58、89、96 和 101 号磁盘块上，那么要存取文件的第 12288 逻辑字节处的信息，应访问（ ）号磁盘块。</p><ul><li>A. 58</li><li>B. 89</li><li>C. 96</li><li>D. 101</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：每块存2个记录(4096/2048=2)。12288/4096=3，第3块(从0计)→101号块。</p><p><strong>已知条件：</strong></p><ul><li>磁盘块大小 = <strong>4096 字节</strong></li><li>每个逻辑记录 = <strong>2048 字节</strong></li><li>所以 <strong>每块存 2 个记录</strong>（4096 ÷ 2048 = 2）</li><li>文件存于 4 个盘块（链式）：<code>58 → 89 → 96 → 101</code></li></ul><p><strong>目标：访问逻辑字节 12288</strong></p><p><strong>第一步：确定在第几个磁盘块</strong></p><p>每块 4096 字节，用逻辑字节数除以块大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12288 ÷ 4096 = 3 （整除，无余数）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>块号（从0计）</th><th>字节范围</th><th>物理块</th></tr></thead><tbody><tr><td>第0块</td><td>0 ~ 4095</td><td>58</td></tr><tr><td>第1块</td><td>4096 ~ 8191</td><td>89</td></tr><tr><td>第2块</td><td>8192 ~ 12287</td><td>96</td></tr><tr><td><strong>第3块</strong></td><td><strong>12288 ~ 16383</strong></td><td><strong>101</strong></td></tr></tbody></table><p>12288 正好是第 3 块的起始位置（第0块是 0~4095 别忘了）。</p><p><strong>第二步：链式存储 → 逐块跟踪</strong></p><p>链式存储下物理块不连续，靠指针串联：</p><ul><li>文件第1块 → 58</li><li>第2块 → 89（58指向89）</li><li>第3块 → 96（89指向96）</li><li><strong>第4块 → 101</strong>（96指向101）</li></ul><p>所以第 3 块（从0计）对应物理块 <strong>101</strong>。</p><p>简单说：12288 ÷ 4096 = 3 → 第 3 块（0-indexed）→ 链式第四个节点 → <strong>101</strong></p></div></details><hr><p><strong>[Q57] 连续结构</strong></p><p>（ ）文件组织方式支持快速随机访问但易产生碎片。</p><ul><li>A. 连续结构</li><li>B. 链接结构</li><li>C. 索引结构</li><li>D. 哈希结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：连续结构=文件块连续存放→随机访问快；但增删文件易产生外碎片。</p></div></details><hr><p><strong>[Q59] 文件属性</strong></p><p>在文件管理系统中，以下哪个文件属性表示该文件是一个系统文件（ ）。</p><ul><li>A. R</li><li>B. A</li><li>C. S</li><li>D. H</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：R=只读(Read-only)，A=归档(Archive)，S=系统(System)，H=隐藏(Hidden)。</p></div></details><hr><p><strong>[Q85] 硬链接</strong></p><p>关于文件的硬链接，下列描述正确的是（ ）。</p><ul><li>A. 创建新的文件实体</li><li>B. 两个文件目录项指向同一个索引节点</li><li>C. 建立文件路径的映射关系</li><li>D. 必须位于同一个文件系统</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：硬链接=多个目录项指向同一inode，不创建新实体，共享同一索引节点。</p><p>D 的描述也是对的，不过更多是约束条件，选择B描述更准确一些。</p></div></details><hr><blockquote><p>⭐ <strong>经典题目</strong> — 索引地址计算核心题（直接/一级间接/二级间接的边界定位）</p></blockquote><p>设文件索引节点有 8 个地址项（每项 4 字节）：5 个直接地址索引，2 个一级间接索引，1 个二级间接索引。磁盘索引块和数据块大小均为 1KB。</p><p><strong>Q1</strong>：访问逻辑块号 5 和 518，分别采用什么索引？</p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>一级间接地址索引和二级间接地址索引</strong></p><p>解析：</p><ul><li>直接索引：0~4（5 个）</li><li>一级间接索引：每节点 1KB/4B=256 个块，2 个节点覆盖 5~516</li><li>二级间接索引：517 以上</li><li>逻辑块 5 在 5~516 范围 → 一级间接；518 &gt; 516 → 二级间接</li></ul><hr><p>答案：逻辑块 5 → <strong>一级间接地址索引</strong>，逻辑块 518 → <strong>二级间接地址索引</strong></p><p>这题是索引结构的经典计算，一步步拆：</p><hr><p>已知条件</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>地址项总数</td><td>8 个（iaddr[0]~iaddr[7]）</td></tr><tr><td>直接索引</td><td>5 个（iaddr[0]~iaddr[4]）</td></tr><tr><td>一级间接索引</td><td>2 个（iaddr[5]~iaddr[6]）</td></tr><tr><td>二级间接索引</td><td>1 个（iaddr[7]）</td></tr><tr><td>磁盘块大小</td><td>1KB = 1024 字节</td></tr><tr><td>每个地址占</td><td>4 字节</td></tr></tbody></table><hr><p>第一步：每个间接节点能管多少块？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个磁盘块可存地址数 = 1024 ÷ 4 = 256 个</span></span></code></pre></div><ul><li><strong>直接索引</strong>：1 个节点管 1 块</li><li><strong>一级间接</strong>：1 个节点管 <strong>256 块</strong></li><li><strong>二级间接</strong>：1 个节点管 256 × 256 = <strong>65536 块</strong></li></ul><hr><p>第二步：画逻辑块号区间图</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地址项        类型          覆盖逻辑块号范围       块数  </span></span>
<span class="line"><span>─────────────────────────────────────────────────────────  </span></span>
<span class="line"><span>iaddr[0]  ─ 直接            0                       1  </span></span>
<span class="line"><span>iaddr[1]  ─ 直接            1                       1  </span></span>
<span class="line"><span>iaddr[2]  ─ 直接            2                       1  </span></span>
<span class="line"><span>iaddr[3]  ─ 直接            3                       1  </span></span>
<span class="line"><span>iaddr[4]  ─ 直接            4                       1  </span></span>
<span class="line"><span>                              ────────  </span></span>
<span class="line"><span>                              0 ~ 4                 5 块  </span></span>
<span class="line"><span>─────────────────────────────────────────────────────────  </span></span>
<span class="line"><span>iaddr[5]  ─ 一级间接         5 ~ 260               256 块  </span></span>
<span class="line"><span>iaddr[6]  ─ 一级间接         261 ~ 516              256 块  </span></span>
<span class="line"><span>                              ────────  </span></span>
<span class="line"><span>                              5 ~ 516              512 块  </span></span>
<span class="line"><span>─────────────────────────────────────────────────────────  </span></span>
<span class="line"><span>iaddr[7]  ─ 二级间接         517 起                 65536 块</span></span></code></pre></div><hr><p>第三步：定位</p><table tabindex="0"><thead><tr><th>逻辑块号</th><th>落在区间</th><th>索引类型</th></tr></thead><tbody><tr><td><strong>5</strong></td><td>5~260（iaddr[5]）</td><td><strong>一级间接索引</strong></td></tr><tr><td><strong>518</strong></td><td>517 以上（iaddr[7]）</td><td><strong>二级间接索引</strong></td></tr></tbody></table><p>答案：逻辑块 5 → <strong>一级间接地址索引</strong>，逻辑块 518 → <strong>二级间接地址索引</strong></p><p>注意边界：逻辑块 4 还是直接索引（iaddr[4]），逻辑块 5 就进入了一级间接</p></div></details><p><strong>Q2</strong>：单个文件最大长度是多少 KB？</p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>66053 KB</strong></p><p>解析：5（直接） + 256×2（一级间接，2个节点各256块） + 256×256（二级间接，256个一级节点各256块）= 5 + 512 + 65536 = 66053 KB</p></div></details><hr><p><strong>[Q18] 索引节点-地址计算</strong></p><p>假设文件系统采用索引节点管理，且索引节点有8个地址项iaddr[0]～iaddr[7]，每个地址项大小为4字节，iaddr[0]～iaddr[4]采用直接地址索引，iaddr[5]和iaddr[6]采用一级间接地址索引，iaddr[7]采用二级间接地址索引。假设磁盘索引块和磁盘数据块大小均为1KB字节。若用户访问文件File1中逻辑块号为5和261的信息，则对应的物理块号分别为（ ）。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260515171817.png" alt="image.png"></p><ul><li>A. 89和90</li><li>B. 89和136</li><li>C. 58和187</li><li>D. 90和136</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：直接索引0~4(5块)覆盖逻辑块0~4；一级间接=256块/节点。逻辑块5→iaddr[5]一级间接第0项→58；逻辑块261→261-5=256→iaddr[6]一级间接第0项→187。</p></div></details><hr><p><strong>[Q19] 索引节点-间接索引</strong></p><p>同上题条件。101号物理块存放的是（ ）。</p><ul><li>A. File1的信息</li><li>B. 直接地址索引表</li><li>C. 一级地址索引表</li><li>D. 二级地址索引表</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：iaddr[7]二级间接→先读一级索引块→再读二级索引块。101号块是二级地址索引表。</p></div></details><hr><p><strong>[Q3] 段式存储-越界原因</strong></p><p>假设系统采用段式存储管理方法。逻辑地址不能转换为对应的物理地址；不能转换的原因是进行（ ）。</p><ul><li>A. 除法运算时除数为零</li><li>B. 算术运算时有溢出</li><li>C. 逻辑地址到物理地址转换时地址越界</li><li>D. 物理地址到逻辑地址转换时地址越界</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：偏移&gt;段长→地址越界，发生在逻辑地址→物理地址转换过程中。</p></div></details><hr><p><strong>[Q51] 段页式地址</strong></p><p>在段页式存储管理中，逻辑地址由（ ）组成。</p><ul><li>A. 段号、页号和页内偏移量</li><li>B. 段号和段内偏移量</li><li>C. 页号和页内偏移量</li><li>D. 段号和页号</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：段页式=先分段再分页，逻辑地址=段号+页号+页内偏移。</p></div></details><hr>`,50)),o(n,{color:"#4bacc6"},{default:i(()=>[...t[7]||(t[7]=[s("逻辑地址转物理地址",-1)])]),_:1}),t[11]||(t[11]=a(`<p>某系统页面大小为 4K，进程页面变换表如下，逻辑地址为十六进制 1D16H，求物理地址。</p><table tabindex="0"><thead><tr><th>页号</th><th>物理块号</th></tr></thead><tbody><tr><td>0</td><td>1</td></tr><tr><td>1</td><td>3</td></tr><tr><td>2</td><td>4</td></tr><tr><td>3</td><td>6</td></tr></tbody></table><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>3D16H</strong></p><p><strong>核心原理：页内偏移不动，页号查表替换成物理块号。</strong></p><p>分页地址转换的本质是逻辑地址 → 物理地址时，<strong>页内偏移直接搬运，只有页号被替换</strong>。因为页面大小就是物理块大小，页内偏移在逻辑地址和物理地址中是相同的。</p><p><strong>步骤拆解：</strong></p><p>① 页面大小 4K = 2^12 → <strong>页内偏移占 12 位</strong>（低 12 位），剩余高位是<strong>页号</strong></p><p>② 拆分 1D16H：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1D16H = 0001  1101 0001 0110  </span></span>
<span class="line"><span>        ↑___  ↑________________  </span></span>
<span class="line"><span>       页号1    页内偏移 D16H</span></span></code></pre></div><ul><li>低 12 位 = D16H（<strong>页内偏移，直接保留</strong>）</li><li>高 4 位 = 1（逻辑页号，<strong>待映射</strong>）</li></ul><p>③ 查页表：页号 <strong>1</strong> → 物理块号 <strong>3</strong>（页号被替换）</p><p>④ 拼物理地址：物理块号 <strong>3</strong> + 页内偏移 <strong>D16H</strong> = <strong>3D16H</strong></p><p>验证公式：物理地址 = 物理块号 × 页面大小 + 页内偏移</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3 × 4096 + D16H = 3 × 1000H + D16H = 3000H + D16H = 3D16H</span></span></code></pre></div></div></details><hr>`,4)),o(n,{color:"#4bacc6"},{default:i(()=>[...t[8]||(t[8]=[s("页面淘汰",-1)])]),_:1}),t[12]||(t[12]=a(`<p>某进程 4 个页面（0~3），分配 3 个存储块，访问前页面 1 不在内存。根据状态位/访问位/修改位，淘汰哪个页面代价最小？</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241021002739.png" alt="页面表"></p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>3</strong></p><p>解析：淘汰原则—<strong>优先淘汰最近未被访问的，再淘汰最近未被修改的</strong>。页 0、2、3 最近都被访问过，但只有页 3 最近未被修改，淘汰代价最小。</p></div></details><hr><p><strong>[Q56] 缺页中断</strong></p><p>以下情况会触发缺页中断（Page Fault）的是（ ）。</p><ul><li>A. 进程访问的页在物理内存中</li><li>B. 进程访问的页被标记为只读</li><li>C. 进程访问的页既不在内存也不在磁盘</li><li>D. 进程访问的页不在物理内存但存在于磁盘</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：缺页=页不在内存但在磁盘，需要调入。A 正常访问；B 是保护异常；C 是非法访问。</p></div></details><hr><p><strong>[Q106] 页面置换</strong></p><p>当CPU要访问的页面不在内存中时，会引发（1）中断，系统处理该中断的过程称为（2）。</p><ul><li>A. 页面置换</li><li>B. 页面调入</li><li>C. 地址变换</li><li>D. 页面分配</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：缺页中断发生后，处理过程 = <strong>页面置换</strong>（选一页换出→调入所需页）。各选项辨析：</p><table tabindex="0"><thead><tr><th>选项</th><th>是什么</th><th>和缺页处理的关系</th></tr></thead><tbody><tr><td><strong>A. 页面置换</strong></td><td>缺页时选一页换出、调入新页的完整过程</td><td>✅ <strong>正确答案</strong>，就是中断处理过程本身</td></tr><tr><td><strong>B. 页面调入</strong></td><td>从磁盘读页面进内存</td><td>❌ 只是置换中的<strong>一个动作环节</strong>，缺了&quot;换出&quot;不完整</td></tr><tr><td><strong>C. 地址变换</strong></td><td>MMU把逻辑地址翻译成物理地址</td><td>❌ 它是每次内存访问都做的，缺页时它只是<strong>触发者</strong>，不是处理者</td></tr><tr><td><strong>D. 页面分配</strong></td><td>决定进程拥有多少个物理页框</td><td>❌ 属于内存管理<strong>策略</strong>，不参与缺页中断处理</td></tr></tbody></table><p><strong>关系图</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地址变换（C）→ 发现页不在内存 → 触发缺页中断  </span></span>
<span class="line"><span>                                       ↓  </span></span>
<span class="line"><span>                                页面置换（A）  </span></span>
<span class="line"><span>                                 ├─ 选一页换出  </span></span>
<span class="line"><span>                                 └─ 页面调入（B）← 读入目标页</span></span></code></pre></div></div></details><hr><p><strong>[Q40] 系统监视</strong></p><p>第二问</p><p>进行系统监视通常有三种方式：一是通过（ ），如UNIX／Linux系统中的ps、last等；二是通过系统记录文件查阅系统在特定时间内的运行状态；三是集成命令、文件记录和可视化技术的监控工具，如（ ）。</p><ul><li>A. Windows的netstat</li><li>B. Linux的 iptables</li><li>C. Windows的 Perfmon</li><li>D. Linux的top</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：题目第三空考的是&quot;集成命令、文件记录和<strong>可视化技术</strong>&quot;的监控工具，关键词在&quot;可视化&quot;——只有 C 是图形化工具。</p><table tabindex="0"><thead><tr><th>选项</th><th>是什么</th><th>为什么不对/对</th></tr></thead><tbody><tr><td><strong>A. netstat</strong></td><td>Windows 命令行网络统计工具</td><td>❌ 命令行，无图形化</td></tr><tr><td><strong>B. iptables</strong></td><td>Linux 防火墙规则配置工具</td><td>❌ 防火墙，不是监视工具</td></tr><tr><td><strong>C. Perfmon</strong> ✅</td><td>Windows 图形化性能监视器，有图表、曲线、日志</td><td>✅ <strong>集成命令行+记录+可视化</strong></td></tr><tr><td><strong>D. top</strong></td><td>Linux 命令行实时进程查看</td><td>❌ 虽然有界面但依然是命令行交互，不算图形化&quot;可视化技术&quot;</td></tr></tbody></table></div></details><hr><p><strong>[Q99] 应用软件</strong></p><p>下列软件中，属于应用软件的是（ ）。</p><ul><li>A. 操作系统</li><li>B. 设备驱动程序</li><li>C. 财务软件</li><li>D. 编译程序</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：财务软件为特定领域设计→应用软件；其余三项都是系统软件。</p></div></details><hr><p><strong>[Q98] 内核特征</strong></p><p>关于操作系统内核的特征，下列说法错误的是（ ）。</p><ul><li>A. 内核以CPU的最高优先级运行</li><li>B. 内核可以执行特权指令</li><li>C. 内核不需要常驻内存</li><li>D. 内核可以直接访问全部主存空间</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：内核是操作系统的核心，<strong>必须常驻内存</strong>，关机才能卸下。选项辨析：</p><table tabindex="0"><thead><tr><th>选项</th><th>判断</th><th>原因</th></tr></thead><tbody><tr><td><strong>A.</strong> 内核以CPU最高优先级运行</td><td>✅ 正确</td><td>内核运行在<strong>核心态（管态）</strong>，优先级高于所有用户进程</td></tr><tr><td><strong>B.</strong> 内核可以执行特权指令</td><td>✅ 正确</td><td>核心态下可执行所有指令，包括启动I/O、修改页表等<strong>特权指令</strong>；用户态则禁止</td></tr><tr><td><strong>C.</strong> 内核不需要常驻内存</td><td>❌ <strong>错误</strong></td><td>内核负责进程调度、内存管理、中断处理等基础功能，一旦缺页自身都无法运行，因此<strong>必须常驻</strong></td></tr><tr><td><strong>D.</strong> 内核可以直接访问全部主存空间</td><td>✅ 正确</td><td>核心态下<strong>地址空间不受限制</strong>，内核可以访问和管理所有物理内存（包括用户进程的内存区域），用于进程切换、内存分配等操作</td></tr></tbody></table></div></details><hr><p><strong>[Q4] COP基本支持</strong></p><p>面向构件的编程(COP)关注于如何支持建立面向构件的解决方案。面向构件的编程所需要的基本支持包括（ ）。</p><ul><li>A. 继承性、构件管理和绑定、构件标识、访问控制</li><li>B. 封装性、信息隐藏、独立部署、模块安全性</li><li>C. 多态性、模块封装性、后期绑定和装载、安全性</li><li>D. 构件抽象、可替代性、类型安全性、事务管理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：COP四个基本支持=<strong>多态性+模块封装性+后期绑定和装载+安全性</strong>。B选项的封装性没错，但缺少多态性和后期绑定和装载，且混入了&quot;独立部署&quot;（这是构件特性，不是COP语言级支持）。</p></div></details><hr><p><strong>[Q79] CORBA软总线</strong></p><p>CORBA架构中，作为&quot;软总线&quot;的是（ ）。</p><ul><li>A. 公共设施</li><li>B. 公共对象服务</li><li>C. 对象请求代理</li><li>D. 对象适配器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：ORB（对象请求代理）=CORBA核心，相当于&quot;软总线&quot;，负责透明传递请求，将客户端调用路由到服务端的Servant。</p></div></details><hr><p><strong>[Q6] 构件描述</strong></p><p>关于构件的描述，正确的是（ ）。</p><ul><li>A. 构件包含了一组需要同时部署的原子构件</li><li>B. 构件可以单独部署，原子构件不能被单独部署</li><li>C. 一个原子构件可以同时在多个构件家族中共享</li><li>D. 一个模块可以看作带有单独资源的原子构件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：构件（Component）和原子构件（Atomic Component）的关系：</p><ul><li><strong>构件</strong> = 包含一组需同时部署的原子构件，可单独部署</li><li><strong>原子构件</strong> = 构件内部的组成单元，不能单独部署（必须和同组其他原子构件一起部署）</li><li>❌ B说法本身没错但不够精确——如果构件只含一个原子构件，该原子构件本身也就是构件，可单独部署</li><li>❌ C原子构件不能同时在多个构件家族中共享（共享应通过接口实现）</li><li>❌ D&quot;模块&quot;是代码组织单位，&quot;原子构件&quot;是部署单位，两者维度不同</li></ul><p>记忆：构件=整包快递（可单独寄），原子构件=包裹里的物品（不能单独寄，要整包走）</p><p>理解两个概念</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────┐  </span></span>
<span class="line"><span>│        构件               │  </span></span>
<span class="line"><span>│  ┌─────┐ ┌─────┐ ┌─────┐ │  </span></span>
<span class="line"><span>│  │原子  │ │原子  │ │原子  │ │  ← 一组原子构件打包在一起  </span></span>
<span class="line"><span>│  │构件A │ │构件B │ │构件C │ │     必须同时部署  </span></span>
<span class="line"><span>│  └─────┘ └─────┘ └─────┘ │  </span></span>
<span class="line"><span>└──────────────────────────┘  </span></span>
<span class="line"><span>    可以单独部署 ✓          不可单独部署 ❌</span></span></code></pre></div><ul><li><strong>构件</strong>（Component）：自包容的程序集，<strong>可以单独部署</strong></li><li><strong>原子构件</strong>（Atomic Component）：构件内部的组成单元，<strong>不能单独部署</strong>，必须和同组的其他原子构件一起部署</li></ul></div></details><hr><p><strong>[Q7] 中断</strong></p><p>第二问</p><p>嵌入式系统中采用中断方式实现输入输出的主要原因是（ ）。在中断时，CPU断点信息一般保存到（ ）中。</p><ul><li>A. 通用寄存器</li><li>B. 堆</li><li>C. 栈</li><li>D. I/O接口</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：</p><p><strong>第一空</strong>（题干未列选项）：嵌入式用中断方式输入输出的主要原因是<strong>提高CPU利用率</strong>——避免轮询（Polling）空转，设备准备好在通知CPU。</p><p><strong>第二空</strong>：CPU断点信息（PC/PSW等）保存到<strong>栈</strong>中。</p><p>各选项分析：</p><table tabindex="0"><thead><tr><th>选项</th><th>判断</th><th>原因</th></tr></thead><tbody><tr><td>A. 通用寄存器</td><td>❌</td><td>数量有限，嵌套中断不够用</td></tr><tr><td>B. 堆</td><td>❌</td><td>用于动态内存分配，不是压栈出栈场景</td></tr><tr><td><strong>C. 栈</strong></td><td>✅</td><td><strong>后进先出</strong>，天然支持中断嵌套</td></tr><tr><td>D. I/O接口</td><td>❌</td><td>外设接口，不存程序状态</td></tr></tbody></table><p><strong>为什么栈适合</strong>：中断嵌套时，后发生的中断先处理、先压栈的后出栈，栈的LIFO特性完美匹配中断恢复顺序。</p></div></details><hr><p><strong>[Q15] 紧耦合SMP</strong></p><p>紧耦合多机系统一般通过（ ）实现多机间的通信。对称多处理器结构（SMP）属于（ ）系统。</p><ul><li>A. 因特网</li><li>B. 共享内存</li><li>C. 进程通信</li><li>D. 共享寄存器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：紧耦合=共享内存通信；松耦合=消息传递。SMP=多个CPU对称访问共享内存。</p></div></details><hr><p><strong>[Q45] 多核调度</strong></p><p>关于多核CPU环境下进程的调度算法，以下说法正确的是（ ）。</p><ul><li>A. 全局队列调度优点是缓存利用率高</li><li>B. 全局队列调度缺点是CPU利用率低</li><li>C. 局部队列调度优点是从全局任务等待队列中选取就绪任务并执行</li><li>D. 局部队列调度缺点是CPU利用率低</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：全局队列=CPU利用率高+缓存利用率低；局部队列=缓存利用率高+CPU利用率低。</p></div></details><hr><p><strong>[Q94] 网络OS</strong></p><p>网络操作系统的硬件独立性是指（ ）。</p><ul><li>A. 只能在特定硬件平台上运行</li><li>B. 可以运行在不同网络硬件上并能与其他网络连接</li><li>C. 必须使用专用的网络设备</li><li>D. 不需要考虑硬件兼容性问题</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：硬件独立性=网络OS<strong>不依赖特定硬件平台</strong>，可运行在不同网络硬件上并能互通。</p><table tabindex="0"><thead><tr><th>选项</th><th>判断</th><th>原因</th></tr></thead><tbody><tr><td>A. 只能在特定硬件运行</td><td>❌</td><td>这是&quot;硬件依赖&quot;，和&quot;独立&quot;反着来</td></tr><tr><td><strong>B. 可运行在不同网络硬件上并连接</strong></td><td>✅</td><td>正确定义，不绑定网卡/交换机品牌</td></tr><tr><td>C. 必须用专用网络设备</td><td>❌</td><td>也是依赖，不是独立</td></tr><tr><td>D. 不需要考虑硬件兼容性</td><td>❌</td><td>太绝对——NOS通过驱动层屏蔽差异，不是&quot;不考虑&quot;</td></tr></tbody></table></div></details><hr><p><strong>[Q35] 工作流</strong></p><p>工作流表示的是业务过程模型，通常使用图形形式来描述，以下不可用来描述工作流的是（ ）。</p><ul><li>A. 活动图</li><li>B. BPMN</li><li>C. 用例图</li><li>D. Petri-Net</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：用例图描述<strong>系统功能和参与者</strong>，不描述业务流程。其余三项均可描述工作流：</p><table tabindex="0"><thead><tr><th>选项</th><th>能否</th><th>原因</th></tr></thead><tbody><tr><td><strong>A. 活动图</strong></td><td>✅</td><td>UML活动图，专画业务流程和并发</td></tr><tr><td><strong>B. BPMN</strong></td><td>✅</td><td>业务流程建模标注，就是干这个的</td></tr><tr><td><strong>C. 用例图</strong></td><td>❌</td><td>描述功能需求，不画流程</td></tr><tr><td><strong>D. Petri-Net</strong></td><td>✅</td><td>数学建模工具，能描述并发/同步/冲突等流程特性</td></tr></tbody></table></div></details><hr><p><strong>[Q37] 数据资产</strong></p><p>数据资产的特征包括（ ）。①可增值 ②可测试 ③可共享 ④可维护 ⑤可控制 ⑥可量化</p><ul><li>A. ①②③④</li><li>B. ①②③⑤</li><li>C. ①②④⑤</li><li>D. ①③⑤⑥</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：数据资产特征：可增值、可共享、可控制、可量化。不含&quot;可测试&quot;和&quot;可维护&quot;。</p></div></details><hr><p><strong>[Q91] 键值数据库</strong></p><p>关于键值数据库的特点，下列描述正确的是（ ）。</p><ul><li>A. 数据以二维表形式存储</li><li>B. 数据以列形式存储</li><li>C. 数据以键值对集合形式存储</li><li>D. 数据以文档格式存储</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：键值数据库=key-value对集合；A 是关系型；B 是列存储；D 是文档数据库。</p></div></details><hr><p><strong>[Q92] 早期数据库</strong></p><p>下列选项中，不属于早期数据库三种主要类型的是（ ）。</p><ul><li>A. 层次式数据库</li><li>B. 网络式数据库</li><li>C. 键值数据库</li><li>D. 关系型数据库</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：早期三种：层次、网络、关系型。键值数据库是NoSQL时代的产物。</p></div></details>`,85))])}const D=p(e,[["render",h]]);export{A as __pageData,D as default};
